using Servicio.RetazoMarket.Business.DTOs.Producto;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Models;using Servicio.RetazoMarket.DataManagment.Models.Common;
namespace Servicio.RetazoMarket.Business.Services;
public class ProductoService:IProductoService {private readonly IProductoDataService _data;private readonly ILineaDataService _lineas;private readonly IProductoFabricacionDataService _fabricacion;private readonly IProductoMaterialDataService _recetas;private readonly IMaterialDataService _materiales;public ProductoService(IProductoDataService data,ILineaDataService lineas,IProductoFabricacionDataService fabricacion,IProductoMaterialDataService recetas,IMaterialDataService materiales)=>(_data,_lineas,_fabricacion,_recetas,_materiales)=(data,lineas,fabricacion,recetas,materiales);public async Task<IReadOnlyList<ProductoResponse>> ObtenerTodosAsync(CancellationToken ct=default)=>(await _data.ObtenerTodosAsync(ct)).Select(ProductoBusinessMapper.ToResponse).ToList();public async Task<ProductoResponse?> ObtenerPorIdAsync(int id,CancellationToken ct=default){var m=await _data.ObtenerPorIdAsync(id,ct);return m is null?null:ProductoBusinessMapper.ToResponse(m);}public async Task<ProductoResponse?> ObtenerPorNombreAsync(string n,CancellationToken ct=default){var m=await _data.ObtenerPorNombreAsync(n.Trim(),ct);return m is null?null:ProductoBusinessMapper.ToResponse(m);}public async Task<DataPagedResult<ProductoResponse>> BuscarAsync(ProductoFiltroRequest f,CancellationToken ct=default){var e=ProductoValidator.ValidarFiltro(f);if(e.Any())throw new ValidationException("Filtro inválido.",e);var x=await _data.BuscarAsync(new ProductoFiltroDataModel{nombre=f.nombre?.Trim(),id_linea=f.id_linea,estado=f.estado?.Trim().ToUpperInvariant(),es_personalizable=f.es_personalizable?.Trim().ToUpperInvariant(),tiene_descuentos=f.tiene_descuentos?.Trim().ToUpperInvariant(),conStock=f.con_stock,precioMinimo=f.precio_minimo,precioMaximo=f.precio_maximo,PageNumber=f.page_number,PageSize=f.page_size},ct);return new(){Items=x.Items.Select(ProductoBusinessMapper.ToResponse).ToList(),PageNumber=x.PageNumber,PageSize=x.PageSize,TotalRecords=x.TotalRecords};}public async Task<ProductoResponse> CrearAsync(CrearProductoRequest r,CancellationToken ct=default){var e=ProductoValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);if(r.tiene_descuentos.Trim().ToUpperInvariant()!="N")throw new ValidationException("Un producto nuevo debe iniciar sin descuentos; active una regla de descuento.");await LineaActiva(r.id_linea,ct);if(await _data.ExistePorNombreAsync(r.prod_nombre.Trim(),ct))throw new ValidationException("Ya existe un producto con ese nombre.");var precio=ProductoBusinessMapper.CalcularPrecio(r.costo_mat_prim,r.costo_mano_obra,r.porcentaje_margen_ganancia,r.porcentaje_gastos_fijos,r.porcentaje_gastos_operativos);return ProductoBusinessMapper.ToResponse(await _data.CrearAsync(ProductoBusinessMapper.ToDataModel(r,precio),ct));}public async Task<ProductoResponse?> ActualizarAsync(ActualizarProductoRequest r,CancellationToken ct=default){var e=ProductoValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);var actual=await _data.ObtenerPorIdAsync(r.id_producto,ct);if(actual is null)return null;if(r.tiene_descuentos.Trim().ToUpperInvariant()!=actual.tiene_descuentos)throw new ValidationException("El indicador de descuentos se administra mediante las reglas de descuento.");await LineaActiva(r.id_linea,ct);var otro=await _data.ObtenerPorNombreAsync(r.prod_nombre.Trim(),ct);if(otro is not null&&otro.id_producto!=r.id_producto)throw new ValidationException("Ya existe otro producto con ese nombre.");var precio=ProductoBusinessMapper.CalcularPrecio(r.costo_mat_prim,r.costo_mano_obra,r.porcentaje_margen_ganancia,r.porcentaje_gastos_fijos,r.porcentaje_gastos_operativos);var x=await _data.ActualizarAsync(ProductoBusinessMapper.ToDataModel(r,precio,actual.stock_actual,actual.tiene_descuentos),ct);return x is null?null:ProductoBusinessMapper.ToResponse(x);}public Task<bool> EliminarAsync(int id,CancellationToken ct=default)=>_data.EliminarLogicoAsync(id,ct);private async Task LineaActiva(int id,CancellationToken ct){var l=await _lineas.ObtenerPorIdAsync(id,ct);if(l is null||l.lin_estado!="ACT")throw new ValidationException("La línea no existe o está inactiva.");}public async Task<ProductoResponse> RegistrarFabricacionAsync(RegistrarProductoFabricadoRequest r,CancellationToken ct=default){if(r is null||r.cantidad_fabricada<=0)throw new ValidationException("La cantidad fabricada debe ser mayor que cero.");if(string.IsNullOrWhiteSpace(r.motivo)||r.motivo.Trim().Length>100)throw new ValidationException("El motivo es obligatorio y admite hasta 100 caracteres.");if(r.id_producto.HasValue==(r.producto_nuevo is not null))throw new ValidationException("Indique un producto existente o uno nuevo, pero no ambos.");ProductoDataModel? nuevo=null;IReadOnlyCollection<ProductoMaterialDataModel> receta;if(r.id_producto.HasValue){var p=await _data.ObtenerPorIdAsync(r.id_producto.Value,ct)??throw new ValidationException("El producto no existe.");receta=await _recetas.ObtenerPorProductoAsync(p.id_producto,ct);if(receta.Count==0)throw new ValidationException("El producto no tiene receta configurada.");}else{var e=ProductoValidator.Validar(r.producto_nuevo!);if(e.Any())throw new ValidationException("El producto nuevo no es válido.",e);if(r.producto_nuevo!.tiene_descuentos.Trim().ToUpperInvariant()!="N")throw new ValidationException("Un producto nuevo debe iniciar sin descuentos.");await LineaActiva(r.producto_nuevo!.id_linea,ct);if(await _data.ExistePorNombreAsync(r.producto_nuevo.prod_nombre.Trim(),ct))throw new ValidationException("Ya existe un producto con ese nombre.");if(r.receta.Count==0)throw new ValidationException("La receta es obligatoria.");var precio=ProductoBusinessMapper.CalcularPrecio(r.producto_nuevo.costo_mat_prim,r.producto_nuevo.costo_mano_obra,r.producto_nuevo.porcentaje_margen_ganancia,r.producto_nuevo.porcentaje_gastos_fijos,r.producto_nuevo.porcentaje_gastos_operativos);nuevo=ProductoBusinessMapper.ToDataModel(r.producto_nuevo,precio);receta=r.receta.Select(ProductoMaterialBusinessMapper.ToDataModel).ToList();}if(receta.Select(x=>x.id_material).Distinct().Count()!=receta.Count)throw new ValidationException("La receta contiene materiales duplicados.");var consumos=new List<FabricacionMaterialDataModel>();foreach(var item in receta){if(item.cantidad_req<=0||decimal.Round(item.cantidad_req,3)!=item.cantidad_req)throw new ValidationException("La receta contiene cantidades inválidas.");if(item.es_personalizable is not("S" or "N"))throw new ValidationException("La receta contiene indicadores inválidos.");if(nuevo is not null&&item.es_personalizable=="S"&&nuevo.es_personalizable!="S")throw new ValidationException("Un material personalizable requiere un producto personalizable.");var material=await _materiales.ObtenerPorIdAsync(item.id_material,ct)??throw new ValidationException($"El material {item.id_material} no existe.");if(material.mat_estado!="ACT")throw new ValidationException($"El material {material.mat_nombre} está inactivo.");var consumo=item.cantidad_req*r.cantidad_fabricada;if(material.stock_actual<consumo)throw new ValidationException($"Stock insuficiente para el material {material.mat_nombre}.");consumos.Add(new(){id_material=item.id_material,cantidad_consumir=consumo});}try{var result=await _fabricacion.RegistrarAsync(new(){id_producto=r.id_producto,ProductoNuevo=nuevo,RecetaNueva=nuevo is null?[]:receta,Materiales=consumos,cantidad_fabricada=r.cantidad_fabricada,motivo=r.motivo.Trim()},ct);return ProductoBusinessMapper.ToResponse(result);}catch(InvalidOperationException ex){throw new ValidationException(ex.Message);}}}
